def select(pool, n_rsrv, max_bs, n_slots):
    batch = []
    for req in sorted(pool, key=lambda r: r.arrival):  # FCFS
        if req.state == "RUNNING":
            continue
        if len(batch) == max_bs:
            break
        if req.state == "INITIATION":           # first time scheduled
            if n_rsrv + req.max_tokens > n_slots:
                break                           # cannot guarantee it
            n_rsrv += req.max_tokens            # reserve worst case
        batch.append(req)
    return batch, n_rsrv

import math, random
from collections import deque

class Request:
    def __init__(self, rid, arrival, prompt, output, max_tokens=None):
        self.id, self.arrival = rid, arrival
        self.prompt, self.output = prompt, output  # output is hidden
        self.max_tokens = max_tokens or output     # client's cap
        self.done = 0        # tokens whose KV is computed
        self.gen = 0         # tokens generated so far
        self.blocks = []     # block table
        self.first = self.end = None
        self.times = []      # time of every output token

    def need(self):          # tokens to compute before next sample
        return self.prompt + self.gen - self.done

class BlockManager:
    def __init__(self, num_blocks, block_size):
        self.free = deque(range(num_blocks))
        self.bs = block_size

    def blocks_for(self, tokens):
        return math.ceil(tokens / self.bs)

    def can_allocate(self, req, tokens):
        extra = self.blocks_for(tokens) - len(req.blocks)
        return extra <= len(self.free)

    def allocate(self, req, tokens):  # grow to hold tokens
        while len(req.blocks) < self.blocks_for(tokens):
            req.blocks.append(self.free.popleft())

    def free_all(self, req):
        self.free.extend(req.blocks)
        req.blocks = []

# Llama 3 8B on one A100-80GB, peak rates (the GPU course's model)
N, WEIGHT_BYTES, PEAK, BW = 8e9, 16e9, 312e12, 2.039e12

def step_time(batch):          # seconds; KV reads ignored
    tokens = sum(n for _, n in batch)
    return max(WEIGHT_BYTES / BW, 2 * N * tokens / PEAK)

def simulate(reqs, sched, trace=False):
    pending = sorted(reqs, key=lambda r: r.arrival)
    clock, steps, busy = 0.0, 0, 0
    while pending or sched.waiting or sched.running:
        while pending and pending[0].arrival <= clock:
            sched.waiting.append(pending.pop(0))
        batch = sched.step()
        if not batch:
            if not pending:
                raise RuntimeError("stuck: a request never fits")
            clock = pending[0].arrival
            continue
        clock += step_time(batch); steps += 1
        busy += len(sched.running)
        if trace:
            print(f"step {steps}:", " ".join(
                f"{r.id} {'d' if r.gen and n == 1 else 'p'}{n}"
                for r, n in batch))
        for r, n in batch:
            r.done += n
            if r.done == r.prompt + r.gen:     # sample a token
                r.gen += 1; r.times.append(clock)
                if r.first is None:
                    r.first = clock
                if r.gen == r.output:
                    r.end = clock
                    sched.running.remove(r)
                    sched.bm.free_all(r)
    return steps, busy / steps
